Python<pre><code>def parse_dependencies(deps: list[str]) -&gt; list[dict[str, str]]:
    """Parse dependency specifications."""
    parsed = []
    for dep in deps:
        # Parse requirement specifier
        if "&gt;=" in dep:
            name, version = dep.split("&gt;=")
            parsed.append({
                "name": name,
                "version": f"&gt;={version}",
                "type": "runtime"
            })
        else:
            parsed.append({
                "name": dep,
                "version": "*",
                "type": "runtime"
            })
