Python<pre><code>from flavor.psp.format_2025.metadata import resolve_dependencies

def resolve_dependencies(
    metadata: PackageMetadata,
    available: dict[str, list[str]]
) -&gt; list[str]:
    """Resolve package dependencies."""
    resolved = []

    for dep in metadata.dependencies:
        # Parse dependency
        if "&gt;=" in dep:
            name, min_version = dep.split("&gt;=")
        else:
            name, min_version = dep, "0.0.0"

        # Find compatible version
        if name in available:
            versions = available[name]
            compatible = [v for v in versions if v &gt;= min_version]
            if compatible:
                resolved.append(f"{name}=={compatible[-1]}")

    return resolved
</code></pre>

