Python<pre><code>import subprocess

def add_git_metadata(metadata: PackageMetadata) -&gt; PackageMetadata:
    """Add git information to metadata."""
    try:
        # Get current commit
        commit = subprocess.check_output(
            ["git", "rev-parse", "HEAD"],
            text=True
        ).strip()

        # Get current branch
        branch = subprocess.check_output(
            ["git", "rev-parse", "--abbrev-ref", "HEAD"],
            text=True
        ).strip()

        # Check if dirty
        status = subprocess.check_output(
            ["git", "status", "--porcelain"],
            text=True
        )
        is_dirty = bool(status.strip())

        return attrs.evolve(
            metadata,
            custom={
                **metadata.custom,
                "git_commit": commit[:8],
                "git_branch": branch,
                "git_dirty": is_dirty
            }
        )
    except subprocess.CalledProcessError:
        return metadata  # Not a git repository
